using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml.Linq;
using System.IO.Compression;
using System.Collections.Generic;
namespace JingFamily {
 public static class TemplateTests {
  public static int Run(string dir){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Template test: "+label);count++;};Action<Action,string> reject=(a,label)=>{bool caught=false;try{a();}catch{caught=true;}check(caught,label);};
   Templates.ExportBundle(Path.Combine(dir,"templates"));string blank=Path.Combine(dir,"templates","景·谱-成员导入模板.xlsx"),example=Path.Combine(dir,"templates","景·谱-填写示例.xlsx");reject(()=>Templates.Read(blank),"blank template does not import example sheet");var excel=Templates.Read(example);check(excel.Data.People.Count==3,"Excel example people");var csv=Templates.Read(Path.Combine(dir,"templates","景·谱-填写示例.csv"));check(csv.Data.People.Count==3,"CSV example people");check(csv.Data.People[2].FatherId==csv.Data.People[0].Id&&csv.Data.People[2].MotherId==csv.Data.People[1].Id,"CSV references");check(csv.Data.People[0].Spouses.Contains(csv.Data.People[1].Id),"spouse reciprocal");
   var records=new List<string[]>{new[]{"编号","姓名","生平"},new[]{"001","张,甲","含逗号,及\"引号\"\r\n还有换行"}};string tricky=String.Join("\r\n",records.Select(r=>String.Join(",",r.Select(Store.Csv))));var parsed=Templates.ParseCsv(tricky);check(parsed[1][2]==records[1][2],"CSV quoted comma quote newline");var imported=Templates.ReadRows(parsed,"test");check(imported.SourceIds.Values.Single()=="001","leading zero identifier");reject(()=>Templates.ParseCsv("编号,姓名\r\n1,\"unclosed"),"unclosed quote");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名\r\n1,甲\r\n1,乙"),"test"),"duplicate ID");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,父亲编号\r\n1,甲,999"),"test"),"unknown reference");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,出生日期\r\n1,甲,2023-02-29"),"test"),"invalid date");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,父亲编号\r\n1,甲,2\r\n2,乙,1"),"test"),"parent cycle");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,性别\r\n1,甲,M"),"test"),"invalid gender");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,不支持的字段\r\n1,甲,内容"),"test"),"unknown column");
   var one=Templates.ReadRows(Templates.ParseCsv("编号,姓名,配偶编号\r\n1,甲,2\r\n2,乙,"),"test");check(one.Data.People[1].Spouses.Contains(one.Data.People[0].Id),"one sided spouse completed");reject(()=>Templates.ReadRows(Templates.ParseCsv("编号,姓名,配偶编号\r\n1,甲,1"),"test"),"self spouse");
   string gb=Path.Combine(dir,"gb.csv");File.WriteAllText(gb,"编号,姓名\r\n1,景测试",Encoding.GetEncoding(54936));check(Templates.Read(gb).Data.People.Single().Name=="景测试","GB18030 CSV");int before=Store.Data.People.Count;var combined=csv.Combine(true);check(combined.People.Count==before+3&&Store.Data.People.Count==before,"append staging does not mutate existing");check(csv.Combine(false).People.Count==3,"replace staging");
   XNamespace ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";string edited=Path.Combine(dir,"excel-types.xlsx");File.Copy(example,edited);using(var z=ZipFile.Open(edited,ZipArchiveMode.Update)){var old=z.GetEntry("xl/worksheets/sheet1.xml");XDocument doc;using(var s=old.Open())doc=XDocument.Load(s);old.Delete();var name=doc.Descendants(ns+"c").First(x=>(string)x.Attribute("r")=="B2");name.SetAttributeValue("t","s");name.RemoveNodes();name.Add(new XElement(ns+"v","0"));var date=doc.Descendants(ns+"c").First(x=>(string)x.Attribute("r")=="D2");date.Attribute("t").Remove();date.SetAttributeValue("s","4");date.RemoveNodes();date.Add(new XElement(ns+"v",DateTime.Parse("1938-03-12").ToOADate().ToString(System.Globalization.CultureInfo.InvariantCulture)));using(var s=z.CreateEntry("xl/worksheets/sheet1.xml").Open())doc.Save(s);using(var w=new StreamWriter(z.CreateEntry("xl/sharedStrings.xml").Open(),Encoding.UTF8))w.Write("<sst xmlns='"+ns+"'><si><t>共享姓名</t></si></sst>");var style=z.GetEntry("xl/styles.xml");XDocument styles;using(var s=style.Open())styles=XDocument.Load(s);style.Delete();styles.Root.Element(ns+"cellXfs").Add(new XElement(ns+"xf",new XAttribute("numFmtId","14"),new XAttribute("fontId","0"),new XAttribute("fillId","0"),new XAttribute("borderId","0")));styles.Root.Element(ns+"cellXfs").SetAttributeValue("count","5");using(var s=z.CreateEntry("xl/styles.xml").Open())styles.Save(s);}
   var native=Templates.Read(edited);check(native.Data.People[0].Name=="共享姓名","Excel shared strings");check(native.Data.People[0].Birth=="1938-03-12","Excel numeric dates");
   using(var z=ZipFile.Open(edited,ZipArchiveMode.Update)){var old=z.GetEntry("xl/worksheets/sheet1.xml");XDocument doc;using(var s=old.Open())doc=XDocument.Load(s);old.Delete();doc.Descendants(ns+"c").First(x=>(string)x.Attribute("r")=="B2").Add(new XElement(ns+"f","1+1"));using(var s=z.CreateEntry("xl/worksheets/sheet1.xml").Open())doc.Save(s);}reject(()=>Templates.Read(edited),"Excel formulas rejected");
   using(var preview=new ImportPreview(csv)){preview.CreateControl();preview.PerformLayout();check(preview.Text.Contains("景·谱"),"import preview UI");var button=preview.Controls.Find("confirmImport",true).Single();check(button.Bounds.Right<=button.Parent.ClientSize.Width&&button.Bounds.Left>=0,"import button stays inside footer");}using(var logo=Ui.Logo())check(logo.Width==256,"embedded logo");
   Store.Replace(combined,null);Store.Load();check(Store.Data.People.Count==before+3,"append commit and reload");return count;
  }
 }
}
